import 'dart:io';\nimport 'package:intl/intl.dart';\nimport 'package:path_provider/path_provider.dart';\n\nenum PdfTemplateType {\n  cards('cards', 'البطاقات'),\n  reports('reports', 'التقارير'),\n  invoices('invoices', 'الفواتير'),\n  users('users', 'المستخدمين'),\n  backup('backup', 'النسخ الاحتياطي');\n\n  const PdfTemplateType(this.code, this.displayName);\n  final String code;\n  final String displayName;\n}\n\nclass PdfFileManager {\n  static final DateFormat _dateFormat = DateFormat('yyyy-MM-dd');\n  static final DateFormat _timeFormat = DateFormat('HH-mm-ss');\n  static final DateFormat _yearFormat = DateFormat('yyyy');\n  static final DateFormat _monthFormat = DateFormat('MM');\n  static final DateFormat _dayFormat = DateFormat('dd');\n\n  /// إنشاء مجلد منظم حسب التاريخ ونوع القالب\n  static Future<Directory> _createOrganizedDirectory(\n    PdfTemplateType templateType,\n    DateTime date,\n  ) async {\n    final documentsDir = await getApplicationDocumentsDirectory();\n    final numDir = Directory('${documentsDir.path}/NUM');\n    \n    final year = _yearFormat.format(date);\n    final month = _monthFormat.format(date);\n    final day = _dayFormat.format(date);\n    \n    final organizedPath = '${numDir.path}/${templateType.code}/$year/$month/$day';\n    final directory = Directory(organizedPath);\n    \n    if (!await directory.exists()) {\n      await directory.create(recursive: true);\n    }\n    \n    return directory;\n  }\n\n  /// توليد اسم ملف منظم\n  static String _generateFileName(\n    PdfTemplateType templateType,\n    DateTime date, {\n    String? customName,\n    String? suffix,\n  }) {\n    final dateStr = _dateFormat.format(date);\n    final timeStr = _timeFormat.format(date);\n    \n    var fileName = 'NUM_${templateType.code}_$dateStr';\n    \n    if (customName != null && customName.isNotEmpty) {\n      fileName += '_$customName';\n    }\n    \n    if (suffix != null && suffix.isNotEmpty) {\n      fileName += '_$suffix';\n    }\n    \n    fileName += '_$timeStr.pdf';\n    \n    return fileName;\n  }\n\n  /// حفظ ملف PDF في المجلد المنظم\n  static Future<String> savePdfFile(\n    List<int> pdfData,\n    PdfTemplateType templateType, {\n    String? customName,\n    String? suffix,\n    DateTime? date,\n  }) async {\n    final saveDate = date ?? DateTime.now();\n    final directory = await _createOrganizedDirectory(templateType, saveDate);\n    final fileName = _generateFileName(\n      templateType,\n      saveDate,\n      customName: customName,\n      suffix: suffix,\n    );\n    \n    final file = File('${directory.path}/$fileName');\n    await file.writeAsBytes(pdfData);\n    \n    return file.path;\n  }\n\n  /// الحصول على جميع ملفات PDF من نوع معين\n  static Future<List<FileInfo>> getPdfFiles(\n    PdfTemplateType templateType, {\n    DateTime? startDate,\n    DateTime? endDate,\n  }) async {\n    final documentsDir = await getApplicationDocumentsDirectory();\n    final templateDir = Directory('${documentsDir.path}/NUM/${templateType.code}');\n    \n    if (!await templateDir.exists()) {\n      return [];\n    }\n    \n    final files = <FileInfo>[];\n    await for (final entity in templateDir.list(recursive: true)) {\n      if (entity is File && entity.path.endsWith('.pdf')) {\n        final stat = await entity.stat();\n        final fileInfo = FileInfo(\n          file: entity,\n          name: entity.uri.pathSegments.last,\n          createdDate: stat.changed,\n          size: stat.size,\n          templateType: templateType,\n        );\n        \n        // تطبيق فلتر التاريخ\n        if (startDate != null && fileInfo.createdDate.isBefore(startDate)) {\n          continue;\n        }\n        if (endDate != null && fileInfo.createdDate.isAfter(endDate)) {\n          continue;\n        }\n        \n        files.add(fileInfo);\n      }\n    }\n    \n    // ترتيب الملفات حسب التاريخ (الأحدث أولاً)\n    files.sort((a, b) => b.createdDate.compareTo(a.createdDate));\n    \n    return files;\n  }\n\n  /// الحصول على جميع ملفات PDF من جميع الأنواع\n  static Future<List<FileInfo>> getAllPdfFiles({\n    DateTime? startDate,\n    DateTime? endDate,\n  }) async {\n    final allFiles = <FileInfo>[];\n    \n    for (final templateType in PdfTemplateType.values) {\n      final files = await getPdfFiles(\n        templateType,\n        startDate: startDate,\n        endDate: endDate,\n      );\n      allFiles.addAll(files);\n    }\n    \n    // ترتيب جميع الملفات حسب التاريخ\n    allFiles.sort((a, b) => b.createdDate.compareTo(a.createdDate));\n    \n    return allFiles;\n  }\n\n  /// حذف الملفات القديمة\n  static Future<int> cleanOldFiles(\n    PdfTemplateType templateType,\n    Duration maxAge,\n  ) async {\n    final documentsDir = await getApplicationDocumentsDirectory();\n    final templateDir = Directory('${documentsDir.path}/NUM/${templateType.code}');\n    \n    if (!await templateDir.exists()) {\n      return 0;\n    }\n    \n    final cutoffDate = DateTime.now().subtract(maxAge);\n    int deletedCount = 0;\n    \n    await for (final entity in templateDir.list(recursive: true)) {\n      if (entity is File && entity.path.endsWith('.pdf')) {\n        final stat = await entity.stat();\n        if (stat.changed.isBefore(cutoffDate)) {\n          await entity.delete();\n          deletedCount++;\n        }\n      }\n    }\n    \n    return deletedCount;\n  }\n\n  /// حساب حجم المجلد\n  static Future<int> getDirectorySize(PdfTemplateType templateType) async {\n    final documentsDir = await getApplicationDocumentsDirectory();\n    final templateDir = Directory('${documentsDir.path}/NUM/${templateType.code}');\n    \n    if (!await templateDir.exists()) {\n      return 0;\n    }\n    \n    int totalSize = 0;\n    await for (final entity in templateDir.list(recursive: true)) {\n      if (entity is File) {\n        final stat = await entity.stat();\n        totalSize += stat.size;\n      }\n    }\n    \n    return totalSize;\n  }\n\n  /// تصدير ملفات متعددة في ملف مضغوط\n  static Future<String?> exportFilesAsZip(\n    List<FileInfo> files,\n    String zipName,\n  ) async {\n    try {\n      final documentsDir = await getApplicationDocumentsDirectory();\n      final exportDir = Directory('${documentsDir.path}/NUM/exports');\n      if (!await exportDir.exists()) {\n        await exportDir.create(recursive: true);\n      }\n      \n      // هنا يمكن إضافة كود ضغط الملفات\n      // نحتاج إلى مكتبة archive package\n      \n      return null; // مؤقتاً حتى يتم إضافة مكتبة الضغط\n    } catch (e) {\n      return null;\n    }\n  }\n\n  /// تنظيف المجلدات الفارغة\n  static Future<void> cleanEmptyDirectories() async {\n    final documentsDir = await getApplicationDocumentsDirectory();\n    final numDir = Directory('${documentsDir.path}/NUM');\n    \n    if (!await numDir.exists()) {\n      return;\n    }\n    \n    await _cleanEmptyDirectoriesRecursive(numDir);\n  }\n\n  static Future<void> _cleanEmptyDirectoriesRecursive(Directory dir) async {\n    final entities = await dir.list().toList();\n    \n    for (final entity in entities) {\n      if (entity is Directory) {\n        await _cleanEmptyDirectoriesRecursive(entity);\n        \n        // التحقق مما إذا كان المجلد فارغاً بعد التنظيف\n        final isEmpty = await entity.list().isEmpty;\n        if (isEmpty) {\n          try {\n            await entity.delete();\n          } catch (e) {\n            // تجاهل الأخطاء\n          }\n        }\n      }\n    }\n  }\n\n  /// إنشاء نسخة احتياطية من جميع الملفات\n  static Future<String?> createBackup() async {\n    try {\n      final documentsDir = await getApplicationDocumentsDirectory();\n      final numDir = Directory('${documentsDir.path}/NUM');\n      \n      if (!await numDir.exists()) {\n        return null;\n      }\n      \n      final backupName = 'NUM_Backup_${_dateFormat.format(DateTime.now())}_${_timeFormat.format(DateTime.now())}';\n      \n      // هنا يمكن إضافة كود إنشاء النسخة الاحتياطية\n      \n      return backupName;\n    } catch (e) {\n      return null;\n    }\n  }\n}\n\nclass FileInfo {\n  final File file;\n  final String name;\n  final DateTime createdDate;\n  final int size;\n  final PdfTemplateType templateType;\n\n  FileInfo({\n    required this.file,\n    required this.name,\n    required this.createdDate,\n    required this.size,\n    required this.templateType,\n  });\n\n  String get formattedSize {\n    if (size < 1024) {\n      return '$size B';\n    } else if (size < 1024 * 1024) {\n      return '${(size / 1024).toStringAsFixed(1)} KB';\n    } else {\n      return '${(size / (1024 * 1024)).toStringAsFixed(1)} MB';\n    }\n  }\n\n  String get formattedDate {\n    return DateFormat('yyyy/MM/dd HH:mm').format(createdDate);\n  }\n\n  String get displayName {\n    return name.replaceAll('.pdf', '').replaceAll('_', ' ');\n  }\n}